def _components(grid, bg):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = set(q)
            for y, x in q:
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); cells.add((yy,xx)); q.append((yy,xx))
            comps.append((color, cells))
    return comps

def _shape(cells):
    r0=min(r for r,c in cells); c0=min(c for r,c in cells)
    return tuple(sorted((r-r0,c-c0) for r,c in cells))

def _is_l(cells):
    r0=min(r for r,c in cells); r1=max(r for r,c in cells)
    c0=min(c for r,c in cells); c1=max(c for r,c in cells)
    h,w=r1-r0+1,c1-c0+1
    if h < 3 or w < 3:
        return False
    # An L occupies one complete extreme row and one complete extreme column.
    return (len(cells) == h+w-1 and
            (all((r0,c) in cells for c in range(c0,c1+1)) and all((r,c1) in cells for r in range(r0,r1+1)) or
             all((r0,c) in cells for c in range(c0,c1+1)) and all((r,c0) in cells for r in range(r0,r1+1)) or
             all((r1,c) in cells for c in range(c0,c1+1)) and all((r,c0) in cells for r in range(r0,r1+1)) or
             all((r1,c) in cells for c in range(c0,c1+1)) and all((r,c1) in cells for r in range(r0,r1+1))))

def _distance(a, b):
    # Minimum Manhattan distance between two objects.
    return min(abs(r-y)+abs(c-x) for r,c in a for y,x in b)

def transform(grid):
    g=[row[:] for row in grid]
    bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    comps=_components(g,bg)
    ls=[(i,col,cells) for i,(col,cells) in enumerate(comps) if _is_l(cells)]
    if not ls:
        return g
    key_i,key_color,key_cells=max(ls,key=lambda x:len(x[2]))
    groups={}
    for i,(col,cells) in enumerate(comps):
        if i==key_i:
            continue
        groups.setdefault(_shape(cells),[]).append((i,col,cells))
    candidates=[]
    for group in groups.values():
        if len(group) >= 2:
            # Recolor the member of a repeated shape farthest from the L-shaped color key.
            candidates.extend(((_distance(cells,key_cells),i,col,cells)) for i,col,cells in group)
    if not candidates:
        return g
    _,_,old,cells=max(candidates,key=lambda x:x[0])
    for r,c in cells:
        g[r][c]=key_color
    return g
'''
